/**
 * The project's own Prettier gets the last word on a generated file.
 *
 * `generate` writes the renderer's bytes and then hands the file to whatever
 * Prettier the project itself installed — their version, their configuration.
 * Both facts are proved with a real spawned formatter rather than a mock: the
 * first test symlinks this repository's Prettier into a temp project with a
 * config the catalog's output deliberately disagrees with (`singleQuote`), and
 * asserts the published file came out in the *project's* style. The second
 * installs a Prettier whose bin only fails, and asserts generation still
 * succeeds, warns, and leaves the catalog's bytes in place.
 *
 * The no-Prettier path needs no test of its own: every transcript test runs in
 * a project without an install, and byte-compares written files against the
 * committed goldens.
 */

import { mkdirSync, readFileSync, symlinkSync, writeFileSync } from "node:fs";
import path from "node:path";
import { format } from "prettier";
import { afterEach, describe, expect, it } from "vitest";

import { main } from "../src/cli.ts";
import { capture } from "./helpers/capture.ts";
import { createTempProject, type TempProject } from "./helpers/golden-project.ts";

const REPO = path.resolve(import.meta.dirname, "../../..");
const GOLDEN_ONE = path.resolve(import.meta.dirname, "goldens/recipes/research-quest/one.ts");

describe("the project's own Prettier, after publication", () => {
  let project: TempProject | undefined;

  afterEach(() => {
    project?.dispose();
    project = undefined;
  });

  function written(): string {
    return readFileSync(path.join(project!.dir, "src/content/resonance_theory.ts"), "utf8");
  }

  it("formats the written file with the project's configuration", async () => {
    project = createTempProject();
    mkdirSync(path.join(project.dir, "node_modules"));
    symlinkSync(
      path.join(REPO, "node_modules/prettier"),
      path.join(project.dir, "node_modules/prettier")
    );
    // A configuration the catalog's own output deliberately disagrees with, so
    // equality below can only mean the project's formatter really ran with the
    // project's config.
    writeFileSync(path.join(project.dir, ".prettierrc"), '{ "singleQuote": true }\n');

    const { io, out } = capture(project.dir);
    const code = await main(["generate", "research-quest", "Resonance Theory", "--yes"], io);
    expect(code).toBe(0);
    expect(out()).toBe(`${path.join(project.dir, "src/content/resonance_theory.ts")}\n`);

    const golden = readFileSync(GOLDEN_ONE, "utf8");
    const expected = await format(golden, { parser: "typescript", singleQuote: true });
    expect(expected, "the config must actually change the output").not.toBe(golden);
    expect(written()).toBe(expected);
  });

  it("warns and keeps the generated bytes when the project's Prettier fails", async () => {
    project = createTempProject();
    const fake = path.join(project.dir, "node_modules/prettier");
    mkdirSync(fake, { recursive: true });
    writeFileSync(
      path.join(fake, "package.json"),
      JSON.stringify({ name: "prettier", version: "0.0.0", bin: { prettier: "./bin.js" } })
    );
    writeFileSync(path.join(fake, "bin.js"), 'console.error("boom"); process.exit(1);\n');

    const { io, out, err } = capture(project.dir);
    const code = await main(["generate", "research-quest", "Resonance Theory", "--yes"], io);

    // The file is already the author's by the time formatting runs, so a
    // broken formatter is their tooling problem, said out loud — never a
    // failed generation and never a mutated file.
    expect(code).toBe(0);
    expect(out()).toBe(`${path.join(project.dir, "src/content/resonance_theory.ts")}\n`);
    expect(err()).toContain("warning: the project's Prettier could not format");
    expect(written()).toBe(readFileSync(GOLDEN_ONE, "utf8"));
  });
});
